"""Message schema and validation for the notification server."""
from __future__ import annotations

import json
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any

VALID_TYPES = {"broadcast", "direct", "system"}


class MessageValidationError(ValueError):
    """Raised when an incoming message does not match the expected schema."""


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


@dataclass
class Message:
    type: str
    payload: dict[str, Any] = field(default_factory=dict)
    timestamp: str = field(default_factory=utc_now_iso)

    @classmethod
    def from_json(cls, raw: str) -> "Message":
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, TypeError) as exc:
            raise MessageValidationError(f"invalid JSON: {exc}") from exc
        return cls.from_dict(data)

    @classmethod
    def from_dict(cls, data: Any) -> "Message":
        if not isinstance(data, dict):
            raise MessageValidationError("message must be a JSON object")

        msg_type = data.get("type")
        if msg_type not in VALID_TYPES:
            raise MessageValidationError(
                f"'type' must be one of {sorted(VALID_TYPES)}, got {msg_type!r}"
            )

        payload = data.get("payload", {})
        if not isinstance(payload, dict):
            raise MessageValidationError("'payload' must be an object")

        timestamp = data.get("timestamp") or utc_now_iso()
        if not isinstance(timestamp, str):
            raise MessageValidationError("'timestamp' must be a string")

        return cls(type=msg_type, payload=payload, timestamp=timestamp)

    def to_dict(self) -> dict[str, Any]:
        return {"type": self.type, "payload": self.payload, "timestamp": self.timestamp}

    def to_json(self) -> str:
        return json.dumps(self.to_dict())

"""Thread-safe registry of connected WebSocket clients."""
from __future__ import annotations

import threading
import uuid
from typing import Any, Iterable


class ClientRegistry:
    """Maps client IDs to their WebSocket connection objects.

    Guarded by a plain threading.Lock (rather than asyncio.Lock) so the
    registry stays safe to use even if the server is ever driven from
    multiple threads/event loops, not just a single asyncio loop.
    """

    def __init__(self) -> None:
        self._clients: dict[str, Any] = {}
        self._lock = threading.Lock()

    def add(self, websocket: Any) -> str:
        client_id = str(uuid.uuid4())
        with self._lock:
            self._clients[client_id] = websocket
        return client_id

    def remove(self, client_id: str) -> None:
        with self._lock:
            self._clients.pop(client_id, None)

    def get(self, client_id: str) -> Any | None:
        with self._lock:
            return self._clients.get(client_id)

    def all_ids(self) -> list[str]:
        with self._lock:
            return list(self._clients.keys())

    def all_items(self) -> list[tuple[str, Any]]:
        with self._lock:
            return list(self._clients.items())

    def all_clients(self) -> list[Any]:
        with self._lock:
            return list(self._clients.values())

    def count(self) -> int:
        with self._lock:
            return len(self._clients)

    def __contains__(self, client_id: str) -> bool:
        with self._lock:
            return client_id in self._clients

import json

import pytest

from notification_server.messages import Message, MessageValidationError


def test_valid_broadcast_message_from_json():
    raw = json.dumps({"type": "broadcast", "payload": {"text": "hi"}, "timestamp": "2026-01-01T00:00:00+00:00"})
    message = Message.from_json(raw)
    assert message.type == "broadcast"
    assert message.payload == {"text": "hi"}
    assert message.timestamp == "2026-01-01T00:00:00+00:00"


def test_valid_direct_message_from_dict():
    message = Message.from_dict({"type": "direct", "payload": {"target": "abc", "text": "hi"}})
    assert message.type == "direct"
    assert message.payload["target"] == "abc"


def test_valid_system_message():
    message = Message.from_dict({"type": "system", "payload": {}})
    assert message.type == "system"


@pytest.mark.parametrize("bad_type", [None, "", "unknown", "BROADCAST", 123])
def test_invalid_type_raises(bad_type):
    with pytest.raises(MessageValidationError):
        Message.from_dict({"type": bad_type, "payload": {}})


def test_missing_type_raises():
    with pytest.raises(MessageValidationError):
        Message.from_dict({"payload": {}})


def test_invalid_json_raises():
    with pytest.raises(MessageValidationError):
        Message.from_json("{not valid json")


def test_non_object_json_raises():
    with pytest.raises(MessageValidationError):
        Message.from_json("[1, 2, 3]")


def test_payload_must_be_object():
    with pytest.raises(MessageValidationError):
        Message.from_dict({"type": "broadcast", "payload": "not a dict"})


def test_default_payload_and_timestamp_are_populated():
    message = Message.from_dict({"type": "system"})
    assert message.payload == {}
    assert isinstance(message.timestamp, str) and message.timestamp


def test_to_dict_and_to_json_round_trip():
    message = Message(type="broadcast", payload={"a": 1}, timestamp="2026-01-01T00:00:00+00:00")
    as_dict = message.to_dict()
    assert as_dict == {"type": "broadcast", "payload": {"a": 1}, "timestamp": "2026-01-01T00:00:00+00:00"}
    round_tripped = Message.from_json(message.to_json())
    assert round_tripped == message
